use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

struct Semaphore {
    mutex: Mutex<usize>,
    condvar: std::sync::Condvar,
}

impl Semaphore {
    fn new(permits: usize) -> Self {
        Semaphore {
            mutex: Mutex::new(permits),
            condvar: std::sync::Condvar::new(),
        }
    }

    fn acquire(&self) {
        let mut permits = self.mutex.lock().unwrap();
        while *permits == 0 {
            permits = self.condvar.wait(permits).unwrap();
        }
        *permits -= 1;
    }

    fn release(&self) {
        let mut permits = self.mutex.lock().unwrap();
        *permits += 1;
        self.condvar.notify_one();
    }
}

fn main() {
    let m1 = Arc::new(Mutex::new(()));
    let m2 = Arc::new(Mutex::new(()));
    let sem = Arc::new(Semaphore::new(0));

    let m1a = Arc::clone(&m1);
    let m2a = Arc::clone(&m2);
    let sem_a = Arc::clone(&sem);

    let a = thread::spawn(move || {
        let _g1 = m1a.lock().unwrap();
        sem_a.release();
        let _g2 = m2a.lock().unwrap();
    });

    let m1b = Arc::clone(&m1);
    let m2b = Arc::clone(&m2);
    let sem_b = Arc::clone(&sem);

    let b = thread::spawn(move || {
        let _g2 = m2b.lock().unwrap();
        sem_b.acquire();
        let _g1 = m1b.lock().unwrap();
    });

    let bystander = thread::spawn(|| loop {
        thread::sleep(Duration::from_millis(1));
    });

    a.join().unwrap();
    b.join().unwrap();

    // Bystander runs forever; detach it by not joining.
    drop(bystander);
}
```

Looking at this program, I need to analyze the lock ordering and semaphore handshake.

**Thread A:**
1. Lock `m1`
2. `sem.release()` (increments permits to 1)
3. Lock `m2`

**Thread B:**
1. Lock `m2`
2. `sem.acquire()` (waits for permit)
3. Lock `m1`

Let me trace the interleavings:

- If A runs first: A locks m1, releases sem (permits=1), locks m2. B locks m2... wait, A holds m2. B blocks on m2. A finishes, releases m1 and m2. B locks m2, acquires sem (permits=0), locks m1. Both complete. ✓

- If B runs first: B locks m2, calls `sem.acquire()`. Permits is 0, so B waits on the condvar. A locks m1, releases sem (permits=1, notify_one wakes B). A locks m2 — but B holds m2! A blocks on m2. B wakes up, decrements permits to 0, tries to lock m1 — but A holds m1! **Deadlock.**

This is a classic deadlock: A holds m1 and waits for m2; B holds m2 and waits for m1. The semaphore handshake was supposed to prevent this, but it doesn't, because B acquires the semaphore *after* taking m2, and A takes m2 *after* releasing the semaphore. The handshake ordering is wrong.

The intent of the handshake is to ensure A gets m1 before B tries to get m1, and B gets m2 before A tries to get m2. The correct pattern: A should acquire m1, then signal; B should wait for the signal *before* acquiring m2. That way B doesn't hold m2 while A needs it.

Let me fix: B should `sem.acquire()` first, then lock m2, then lock m1. And A locks m1, releases sem, then locks m2.

Trace with fix:
- B first: B acquires sem — permits 0, waits. A locks m1, releases sem (permits=1, wakes B). A locks m2 (free). A finishes. B wakes, acquires sem (permits=0), locks m2 (free), locks m1 (free). Both complete. ✓
- A first: A locks m1, releases sem (permits=1). A locks m2. B acquires sem (permits=0), locks m2 — blocked until A done. A finishes. B locks m2, locks m1. ✓

No deadlock. The fix is to move `sem_b.acquire()` before `m2b.lock()`.

